const profModules=[],qs=[];
for(const t of tests){const id='prof-'+t.letter.toLowerCase();const groups=[];t.groups.forEach((g,gi)=>{const n=g.n||gi+1,gid=id+'-'+n;groups.push({id:gid,n,title:g.title,instr:g.instr,rule:g.rule});g.items.forEach((it,ii)=>{const [prompt,ans,dis,explain]=it;const answers=expand(Array.isArray(ans)?ans:[ans]);const options=g.write?[answers[0],'Phrase à reconstruire','Écris la phrase complète']:[answers[0],...dis.filter(d=>!answers.includes(d))];const q={id:gid+'-'+(ii+1),module:id,group:gid,prompt,answers,options,explain,hint:g.rule,label:'Ex. '+n+' · '+g.title,source:'Test '+t.letter+', ex. '+n+'.'+(ii+1)};if(g.list)q.list=g.list;if(g.instr)q.instr=g.instr;if(g.write)q.writeOnly=true;if(g.choice)q.choiceOnly=true;qs.push(q)})});profModules.push({id,letter:t.letter,title:'Test '+t.letter+' · Unités '+t.units,desc:'Test de révision Tech Talk, unités '+t.units+'.',rule:'Ressource donnée par la prof pour le contrôle écrit.',pdf:t.pdf,groups,skipped:t.skipped})}
C.profModules=profModules;C.questions.push(...qs);
